// Validate and normalise the request sent by Laravel (POST /api/chat).
const body = $input.first().json.body ?? {};
const message = String(body.message ?? '').trim().slice(0, 1000);
const sessionId = String(body.session_id ?? '').replace(/[^A-Za-z0-9\-]/g, '').slice(0, 64);
if (!message) throw new Error('Missing message');
if (sessionId.length < 16) throw new Error('Missing or invalid session_id');
return [{ json: {
  message,
  session_id: sessionId,
  today: String(body.today ?? new Date().toISOString().slice(0, 10)),
  timezone: String(body.timezone ?? 'Asia/Manila'),
} }];

